import ast


def eval_expression(expr):
    """+、-、*、/ と括弧、単項の負号に対応する式評価関数"""

    tree = ast.parse(expr, mode="eval")

    def evaluate(node):
        # 数値リテラル
        if isinstance(node, ast.Constant):
            if type(node.value) in (int, float):
                return node.value
            raise ValueError("数値以外は使用できません")

        # 単項演算子（例: -3, +5）
        if isinstance(node, ast.UnaryOp):
            value = evaluate(node.operand)

            if isinstance(node.op, ast.USub):
                return -value
            if isinstance(node.op, ast.UAdd):
                return value

            raise ValueError("未対応の単項演算子です")

        # 二項演算子
        if isinstance(node, ast.BinOp):
            left = evaluate(node.left)
            right = evaluate(node.right)

            if isinstance(node.op, ast.Add):
                return left + right
            if isinstance(node.op, ast.Sub):
                return left - right
            if isinstance(node.op, ast.Mult):
                return left * right
            if isinstance(node.op, ast.Div):
                if right == 0:
                    raise ZeroDivisionError("ゼロで割ることはできません")
                return left / right

            raise ValueError("未対応の演算子です")

        raise ValueError("無効な式です")

    return evaluate(tree.body)
```

使用例:

```python
print(eval_expression("3 + 4 * (2 - 1)"))  # 7
print(eval_expression("-3 + 2 * 5"))        # 7
print(eval_expression("10 / 4"))            # 2.5

eval_expression("1 / 0")
# ZeroDivisionError: ゼロで割ることはできません
```

`ast` を使って許可した演算だけを評価するため、`eval()` を直接使うより安全です。

